import{z as l,x as C,o as e,c as i,q as t,j as A,D as E,d as n,s as o,S as B}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"中央对手方与违约瀑布","description":"","frontmatter":{"title":"中央对手方与违约瀑布","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ccp-default-waterfall.md","filePath":"quant/ccp-default-waterfall.md","lastUpdated":1791413859000}'),s={name:"quant/ccp-default-waterfall.md"};function d(p,a,u,D,c,P){const r=C("Mermaid");return e(),i("div",null,[a[2]||(a[2]=t('<h1 id="中央对手方与违约瀑布" tabindex="-1">中央对手方与违约瀑布 <a class="header-anchor" href="#中央对手方与违约瀑布" aria-label="Permalink to &quot;中央对手方与违约瀑布&quot;">​</a></h1><div class="epigraph"><p>成交一旦进入中央对手方，你的对手变成 CCP：它用保证金、违约基金与瀑布规则吸收成员违约。瀑布保护的是系统，不是你的策略夏普。</p><footer>—— CPSS-IOSCO, Principles for Financial Market Infrastructures, 2012；Duffie and Zhu, Does a Central Clearing Counterparty Reduce Counterparty Risk?, RFS, 2011；对照各 CCP 公开的违约管理文件</footer></div><p><a href="/quant/exchange-outages">上一课</a>把「成交是否发生」停在引擎与对账。本课的缺口是<strong>成交之后的对手方是谁</strong>。中央对手方（CCP）通过合约更替（novation）成为每笔已接受成交的买方之卖方、卖方之买方。CPSS-IOSCO《金融市场基础设施原则》（PFMI）把保证金、违约基金、压力测试写成国际标准。Duffie 与 Zhu（2011）问 CCP 是否真降低对手方风险——答案取决于净额、分割与是否把风险集中到少数成员。后课结算失败是瀑布尚未触发时的日常摩擦。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>双边 OTC 下，你跟踪每个对手的信用。集中清算后，你跟踪：初始保证金、变动保证金、违约基金贡献、以及「若某成员违约，损失按什么顺序吃」。瀑布通常自上而下：违约者自己的保证金 → 其违约基金 → CCP 资本的一部分 → 非违约成员违约基金 → 可能的评估权（assessment）与变现工具。问题是策略容量与杠杆受这套水位约束：保证金上调会强制减仓，与 alpha 无关。把期货当「无对手方风险」忽略了成员资格、分仓与连带。</p><p><span class="marginnote">术语翻译：违约瀑布就是把损失按「谁的责任先用谁的钱、再动公共的钱」排序——先倒的会员自己的保证金和基金，再是清算所资本，最后是没违约的会员出钱。像保险的免赔额、共保层、再保层，一层吃穿了才轮到下一层。</span></p><p>净额是 CCP 的微观基础：同一成员、同一合约的多空轧差后再收保证金。跨合约组合保证金（SPAN 一类）进一步按情景收。净额降低总量，但把风险从「许多双边暴露」改成「对单一 CCP 的集中暴露」。Duffie–Zhu 指出：多个 CCP 分割同一经济风险时，净额效率下降，总抵押可能上升。研究跨币种、跨所对冲，必须问两腿是否在同一 CCP 净额池。</p>',7)),(e(),A(B,null,{default:E(()=>[o(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20BIL%5B%22%E5%8F%8C%E8%BE%B9%20OTC%EF%BC%9A%E6%AF%8F%E5%AF%B9%E5%AF%B9%E6%89%8B%E4%B8%80%E6%9D%A1%E4%BF%A1%E7%94%A8%E7%BA%BF%22%5D%20--%3E%20MANY%5B%225%20%E5%AE%B6%E6%9C%BA%E6%9E%84%20%3D%2010%20%E6%9D%A1%E7%BA%BF%EF%BC%8C%E6%AF%8F%E6%9D%A1%E9%83%BD%E8%A6%81%E7%9B%AF%22%5D%0A%20%20CCP2%5B%22%E9%9B%86%E4%B8%AD%E6%B8%85%E7%AE%97%EF%BC%9A%E6%89%80%E6%9C%89%E6%88%90%E5%91%98%E5%8F%AA%E5%AF%B9%20CCP%22%5D%20--%3E%20FEW%5B%225%20%E5%AE%B6%E6%9C%BA%E6%9E%84%20%3D%205%20%E6%9D%A1%E7%BA%BF%EF%BC%8C%E5%87%80%E9%A2%9D%E5%90%8E%E6%9B%B4%E5%B0%91%22%5D%0A%20%20MANY%20--%3E%20Q%5B%22%E5%87%80%E9%A2%9D%E6%95%88%E7%8E%87%E4%B8%8E%E9%9B%86%E4%B8%AD%E6%9A%B4%E9%9C%B2%E7%9A%84%E6%9D%83%E8%A1%A1%22%5D%0A%20%20FEW%20--%3E%20Q%0A%20%20Q%20--%3E%20SPLIT%5B%22%E8%8B%A5%E9%A3%8E%E9%99%A9%E8%A2%AB%E5%A4%9A%E4%B8%AA%20CCP%20%E5%88%86%E5%89%B2%EF%BC%9A%E5%87%80%E9%A2%9D%E6%B1%A0%E5%8F%98%E5%B0%8F%22%5D%0A%20%20SPLIT%20--%3E%20UP%5B%22%E5%90%8C%E4%B8%80%E7%BB%8F%E6%B5%8E%E9%A3%8E%E9%99%A9%E7%9A%84%E6%80%BB%E6%8A%B5%E6%8A%BC%E5%8F%AF%E8%83%BD%E4%B8%8A%E5%8D%87%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h3 id="变动保证金是日内流动性" tabindex="-1">变动保证金是日内流动性 <a class="header-anchor" href="#变动保证金是日内流动性" aria-label="Permalink to &quot;变动保证金是日内流动性&quot;">​</a></h3><p>盯市亏损通过变动保证金（VM）当日或盘中划转。这与<a href="/quant/cn-index-fut-basis">股指期货保证金</a>在 A 股的实现同构：方向对称的现金抽血。策略在压力日的约束往往是 VM 而不是初始保证金——现金调拨失败会把未违约账户拖进运营违约。瀑布是极端；VM 是日常。回测只扣初始保证金、忽略 VM 路径，会低估杠杆策略的爆仓概率。</p><p><span class="marginnote">隔离（segregation）决定违约时客户资产是否被用来填其他客户的坑。规则因司法辖区与账户类型而异。研究「CCP 安全」必须落到账户层级，不能停在「有中央对手方」一句。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把清算状态写入持仓对象：<code>ccp</code>、账户类型（客户/自营）、初始保证金、VM、违约基金预估。压力测试用 CCP 公开的情景或历史压力日（2015 股指、2020 国债、2022 金属），看 VM 路径是否打穿备付。跨所对冲：若两腿不同 CCP，保证金是两套，基差风险不在组合净额里。成员违约不是你的回测默认路径，但「保证金上调 50%」是可观测的政策路径，应进情景。</p><p><span class="marginnote">数字实例：某成员缴初始保证金 5000 万、违约基金份额 2000 万。它违约且头寸亏 8000 万时，先吃它自己的 5000 万，缺口 3000 万依次动用其基金份额与 CCP 资本层；若瀑布继续下探，没违约的你也要按份出钱——这就是「从未与它交易也能被牵连」的量化含义。</span></p><p>违约管理拍卖：CCP 把违约组合拍卖给幸存成员。价格可以远离模型中点，幸存做市商的资本被临时占用。这不是你的策略能「优化」的对象；它解释为何压力日流动性供给收缩——成员在为瀑布预留资金。</p><h3 id="与撮合核的边界" tabindex="-1">与撮合核的边界 <a class="header-anchor" href="#与撮合核的边界" aria-label="Permalink to &quot;与撮合核的边界&quot;">​</a></h3><p>核保证成交事实；CCP 保证（在规则内）清算事实。错误成交 bust 发生在两者之间的窗口，可能改变是否进入 novation。工程上成交回报 ≠ 终局；终局以清算确认为准。量化库存应有 <code>matched / cleared / settled</code> 三态，与<a href="/quant/us-t1-settlement">美国 T+1</a> 的交收钟分开但可对齐。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>novation 把双边信用换成对 CCP 的信用加上成员间的互助。互助通过违约基金产生关联：你从未交易过的成员违约，也能抽走你的基金贡献。这是系统性保险费。瀑布越深，保险越厚，成员的或有杠杆越大。监管要求 Cover-2 一类压力（同时倒两家最大成员）决定基金规模；规模随波动调整，于是「市场中性」组合仍会在保证金周期上被去杠杆。</p><p>A 股期货的 CCP 是中金所等期货交易所清算；股票竞价经中国结算。股票与期货的保证金、净额、违约处置不是同一瀑布。跨市场中性必须分列两套清算约束，见后课中性策略。</p>',12)),(e(),A(B,null,{default:E(()=>[o(r,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20Trade%5B%22%E6%92%AE%E5%90%88%E6%88%90%E4%BA%A4%22%5D%20--%3E%20Nov%5B%22%E5%90%88%E7%BA%A6%E6%9B%B4%E6%9B%BF%20%E8%BF%9B%E5%85%A5%20CCP%22%5D%0A%20%20Nov%20--%3E%20IM%5B%22%E5%88%9D%E5%A7%8B%E4%BF%9D%E8%AF%81%E9%87%91%22%5D%0A%20%20Nov%20--%3E%20VM%5B%22%E5%8F%98%E5%8A%A8%E4%BF%9D%E8%AF%81%E9%87%91%22%5D%0A%20%20Def%5B%22%E6%88%90%E5%91%98%E8%BF%9D%E7%BA%A6%22%5D%20--%3E%20W1%5B%22%E8%BF%9D%E7%BA%A6%E8%80%85%E4%BF%9D%E8%AF%81%E9%87%91%22%5D%0A%20%20W1%20--%3E%20W2%5B%22%E8%BF%9D%E7%BA%A6%E8%80%85%E5%9F%BA%E9%87%91%22%5D%0A%20%20W2%20--%3E%20W3%5B%22CCP%20%E8%B5%84%E6%9C%AC%E5%B1%82%22%5D%0A%20%20W3%20--%3E%20W4%5B%22%E9%9D%9E%E8%BF%9D%E7%BA%A6%E6%88%90%E5%91%98%E5%9F%BA%E9%87%91%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不提供利用客户保证金挪用、或在违约拍卖中操纵价格的方法。瀑布细节以各 CCP 现行规则为准，本课只给结构。双边清算仍占部分 OTC 市场；不要把所有衍生品都写成已集中清算。</p><p><span class="marginnote">直觉类比：CCP 像小区的物业维修基金。平时每户交钱（保证金与基金），一家水管爆了（成员违约）先花他自家的钱，不够再动公共基金；基金见底就全体业主临时摊派（评估权）。「有物业」不等于永不漏水，只等于漏水有人按规矩出钱。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CCP 通过 novation 与净额改变对手方，同时集中风险并创造成员互助。</li><li>日常约束是变动保证金路径；极端约束是瀑布与评估权。</li><li>跨 CCP 对冲没有组合净额；股票与期货清算机构不同。</li><li>出处：CPSS-IOSCO PFMI, 2012；Duffie and Zhu, <em>RFS</em>, 2011。</li></ul>',5))])}const F=l(s,[["render",d]]);export{f as __pageData,F as default};
